const PRODUCTS=[
  {key:'core',n:'01',name:'ARC Core',label:'RUGGED EDGE INTELLIGENCE',short:'Intelligence close to the source.',desc:'Application-defined computing modules bringing local inference, signal processing and sensor intelligence into environments where latency, power and thermal headroom matter.',tone:'tone-blue',group:'Compute / signal processing',art:'core',intro:'When moving data to the cloud is too slow, too costly or inappropriate for the mission, intelligence belongs beside the sensor. ARC Core is a configurable architecture for compact edge processing with the security, power and environmental disciplines treated as part of the compute problem.',focus:['Sensor preprocessing and feature extraction','Local classification and anomaly screening','Data reduction and condition monitoring','FPGA or processor-based interface integration','Resource-aware AI deployment and safe fallback'],subsystems:[['Compute fabric','CPU, NPU, GPU or FPGA selected against actual signal rate, latency, accuracy and power constraints. No processor is prescribed before workload definition.'],['Edge AI runtime','Versioned models, preprocessing, memory budget, runtime profiling, accuracy and fallback behavior assessed on target hardware.'],['System interfaces','Protected sensor/power entry, bandwidth assessment, isolation where needed and defined integration with the host.'],['Secure lifecycle','Secure boot, signed updates, logging and recovery where supported by the selected platform and requirements.']],buyers:'Systems architects, embedded product owners, aerospace and UAS integrators, industrial sensing teams and long-life equipment operators.',deliverables:'Requirements and resource budget; design architecture; prototype integration; repeatable target-device performance and thermal evidence; software and configuration baseline.',readiness:'Custom configurations and qualification routes are discussed against the actual application. No standard performance value or stocked product is claimed.'},
  {key:'guard',n:'02',name:'ARC Guard',label:'ELECTROMAGNETIC RESILIENCE',short:'Integrity at every boundary.',desc:'Protective interface and enclosure engineering to reduce defined electromagnetic and electrical disturbance pathways without compromising intended system behavior.',tone:'tone-navy',group:'EMC / interface protection',art:'guard',intro:'The integrity of a system is often decided where it touches the outside world. Cable entries, power conversion, return-current paths and enclosure discontinuities can turn an otherwise capable product into a vulnerable assembly. ARC Guard addresses that boundary with a system-specific electromagnetic resilience architecture.',focus:['Protected power and signal entries','Enclosure seams and shielding continuity','Grounding, bonding and return-path design','Filtering, isolation and transient protection','EMC pre-compliance and configuration-based evaluation'],subsystems:[['Entry protection','Power/signal conditioning, filtering and transient suppression selected to fit the real waveform and interface bandwidth.'],['Shield architecture','Enclosure, apertures, seams, connector termination and bonding designed as a system rather than isolated components.'],['PCB/package discipline','Layout and return-current decisions that affect coupling, impedance and switching noise.'],['Verification path','Test setup, operating modes, cable configuration, limits, failures, corrective actions and retests documented against agreed criteria.']],buyers:'Aerospace suppliers, autonomous-platform electronics teams, defense subsystem integrators and industrial equipment designers.',deliverables:'Coupling-path assessment; shielding/grounding strategy; protection and filter design; installation guidance; controlled test matrix and configuration-specific results.',readiness:'Resilience is environment-specific. ARC Guard does not imply universal immunity to jamming, EMP or HPM.'},
  {key:'flux',n:'03',name:'ARC Flux',label:'THERMAL-AWARE PACKAGING',short:'Designed around real physics.',desc:'A tightly connected thermal, mechanical and electrical approach to package integration, interposers, substrates and reliable compute density.',tone:'tone-gold',group:'Heat / packaging / interposers',art:'flux',intro:'Computing power creates heat; heat moves through geometry and materials; every solution changes mechanical and electrical behavior. ARC Flux brings those coupled constraints into one package architecture to support demanding electronic systems.',focus:['Thermal path definition and temperature budgets','Package/interposer integration and trade studies','Power and signal integrity in physical stacks','Materials, warpage and thermal expansion review','Prototype characterization and environmental reliability'],subsystems:[['Thermal architecture','Heat source and duty cycle characterization, spreading paths, interface resistance, ambient conditions and allowable temperatures.'],['Interposer integration','Pad/pin mapping, parasitic effects, stack height, mechanical fit, substrate topology and assembly trade-offs.'],['Mechanical reliability','CTE mismatch, retention, warpage, coatings, adhesives, gasketing and thermal cycling considered together.'],['Correlation','Prototype thermal telemetry, measurements and adjustment of model assumptions within defined limits.']],buyers:'Microelectronics developers, rugged compute integrators, researchers, high-altitude systems engineers and long-life equipment teams.',deliverables:'Thermal architecture and budget; interposer/package drawings; materials trade study; prototype build plan; verification and characterization record.',readiness:'No proprietary packaging process, validated temperature rating or production qualification is asserted without project evidence.'},
  {key:'bridge',n:'04',name:'ARC Bridge',label:'ELECTRONICS CONTINUITY',short:'Upgrade the future. Preserve the past.',desc:'Authorized electronic lifecycle extension using replacement interfaces, adapters, approved components and FPGA migration when technically appropriate.',tone:'tone-blue-strong',group:'Lifecycle / retrofit / obsolescence',art:'bridge',intro:'Some systems outlive the components on which they depend. ARC Bridge focuses on continuity: understanding the installed baseline, engineering an authorized replacement path, and proving that the host system still behaves as required.',focus:['Obsolete component and interface assessment','Adapter and interposer replacement pathways','Commercial part substitution with controlled approval','FPGA-based logic migration where justified','Form-fit-function and host-system verification'],subsystems:[['Legacy characterization','Authorized access, interface control, timing, voltage, analog behavior and mechanical fit.'],['Migration options','Comparison of replacement parts, adapter designs, FPGA logic approaches and maintenance implications.'],['Compatibility evidence','Power sequencing, pin mapping, software behavior, thermal/EMC effects and host-system requalification.'],['Sustainment baseline','Approved BOM, alternatives, change record, replacement documentation and obsolescence monitoring plan.']],buyers:'Long-life platform owners, industrial OEMs, aviation suppliers, research systems integrators and sustainment program leaders.',deliverables:'Authorization and scope record; reverse-characterization constraints; trade study; controlled design; prototype; host-integration evidence; lifecycle plan.',readiness:'Modifications require rights or written authorization; form-fit-function equivalence cannot be assumed.'}
];
