function symbolSvg(type){
 const common='<defs><linearGradient id="plA" x1="0" y1="0" x2="1" y2="1"><stop stop-color="var(--art-white)"/><stop offset=".4" stop-color="var(--art-blue-light)"/><stop offset="1" stop-color="var(--art-navy)"/></linearGradient><linearGradient id="plB" x1="0" y1="0" x2="1" y2="1"><stop stop-color="var(--art-white)"/><stop offset=".6" stop-color="var(--art-blue-light)"/><stop offset="1" stop-color="var(--art-blue)"/></linearGradient><linearGradient id="plC" x1="0" y1="0" x2="1" y2="1"><stop stop-color="var(--art-gold-light)"/><stop offset=".5" stop-color="var(--art-gold)"/><stop offset="1" stop-color="var(--art-navy)"/></linearGradient></defs>';
 const v={core:'<ellipse cx="250" cy="245" rx="190" ry="162" fill="none" stroke="var(--art-blue)" stroke-width="2" opacity=".24"/><g transform="rotate(-24 250 250)"><circle cx="250" cy="250" r="169" fill="url(#plA)"/><circle cx="250" cy="250" r="120" fill="var(--art-blue-light)"/><circle cx="250" cy="250" r="89" fill="url(#plB)"/><circle cx="250" cy="250" r="51" fill="var(--art-navy)"/><circle cx="250" cy="250" r="19" fill="var(--art-gold-light)"/></g>',guard:'<g transform="rotate(-18 250 250)"><path d="M250 47 425 145 425 350 250 452 75 350 75 145Z" fill="url(#plB)"/><path d="M250 99 380 171 380 324 250 395 120 324 120 171Z" fill="var(--surface-blue)"/><path d="M250 151 334 197 334 300 250 348 166 300 166 197Z" fill="var(--art-blue)"/><circle cx="250" cy="249" r="42" fill="var(--art-gold-light)"/><circle cx="250" cy="249" r="17" fill="var(--art-navy)"/></g><ellipse cx="250" cy="250" rx="231" ry="140" transform="rotate(-18 250 250)" fill="none" stroke="var(--art-blue)" opacity=".24" stroke-width="2"/>',flux:'<g transform="rotate(-21 250 250)"><rect x="70" y="88" width="360" height="335" rx="71" fill="url(#plC)"/><rect x="113" y="123" width="275" height="262" rx="53" fill="var(--surface-gold)"/><rect x="152" y="163" width="200" height="179" rx="38" fill="var(--brand-gold)"/><rect x="191" y="199" width="120" height="108" rx="22" fill="var(--art-navy)"/><rect x="224" y="231" width="54" height="47" rx="10" fill="var(--art-white)"/></g>',bridge:'<g transform="rotate(-23 250 250)"><rect x="105" y="50" width="290" height="401" rx="62" fill="none" stroke="url(#plB)" stroke-width="54"/><rect x="145" y="99" width="211" height="302" rx="42" fill="url(#plA)"/><rect x="176" y="143" width="149" height="214" rx="31" fill="var(--art-navy)"/><rect x="202" y="179" width="98" height="144" rx="21" fill="var(--art-blue-light)"/><rect x="224" y="207" width="54" height="85" rx="14" fill="var(--art-white)"/></g>'};
 return '<svg viewBox="0 0 500 500" role="img" aria-label="Abstract geometric visualization of '+type+' architecture">'+common+(v[type]||v.core)+'</svg>';
}
const link=(path,text,cls='text-link')=>`<a href="#/${path}" class="${cls}">${text}</a>`;
const eyebrow=(s)=>`<div class="eyebrow"><span class="dot"></span>${s}</div>`;
const ptext=(text)=>`<p>${text}</p>`;
function renderHomeProductCards(){document.getElementById('homeProductGrid').innerHTML=PRODUCTS.map(p=>`<article class="product-card product-card--${p.key}"><div class="product-top"><span>GMS / ${p.n} — ${p.label}</span><a href="#/products/${p.key}" aria-label="Explore ${p.name}">↗</a></div><div class="product-art" aria-hidden="true">${symbolSvg(p.art)}</div><div class="product-copy"><small>${p.group.toUpperCase()}</small><h3>${p.name}</h3><p>${p.desc}</p>${link('products/'+p.key,'Discover the architecture ↗')}</div></article>`).join('')}
function renderHomeSectors(){document.getElementById('sectorRows').innerHTML=SECTORS.map(s=>`<div class="sector-row"><span class="n">${s[0]}</span><h3>${s[1]}</h3><p>${s[2]}</p><a href="#/applications" aria-label="Learn about ${s[1]}">↗</a></div>`).join('')}
const pageHero=(kicker,title,lead,tone,art,ctaLabel='Discuss a configuration')=>`<section class="detail-hero ${tone||''}"><div class="container detail-hero-grid"><div>${eyebrow(kicker)}<h1>${title}</h1><p class="detail-lead">${lead}</p><div class="detail-actions">${link('contact',ctaLabel+' ↗','button')}${link('portfolio','Explore the ARC family ↗','button button-light')}</div></div><div class="detail-object" aria-hidden="true">${symbolSvg(art||'core')}</div></div></section>`;
const detailNav=(links)=>`<div class="container subnav">${links.map(([to,t])=>`<a href="${to.startsWith('#')?to:'#'+to}">${t} ↗</a>`).join('')}</div>`;
const copyBlock=(kicker,heading,body1,body2)=>`<section class="detail-section container"><div class="detail-intro">${eyebrow(kicker)}<h2>${heading}</h2></div><div class="detail-copy">${ptext(body1)}${ptext(body2)}</div></section>`;
function tableRows(rows){return `<div class="detail-table">${rows.map(r=>`<div class="detail-table-row"><h3>${r[0]}</h3><p>${r[1]}</p></div>`).join('')}</div>`}
function featureGrid(items){return `<div class="feature-list">${items.map((r,i)=>`<div class="feature"><small>GMS / ${String(i+1).padStart(2,'0')}</small><div><h3>${r[0]}</h3><p>${r[1]}</p></div></div>`).join('')}</div>`}
function requestPanel(title,body,interest){return `<div class="request-panel"><div><h3>${title}</h3><p>${body}</p></div><a href="#/contact" data-interest="${interest||''}" class="button">Start a technical discussion <span>↗</span></a></div>`}
function pageProduct(p){const elsewhere=PRODUCTS.filter(a=>a.key!==p.key);return pageHero('GMS / ARC '+p.n+' — '+p.label,`${p.name.replace('ARC','ARC <em>')}</em>`,p.intro,p.tone,p.art,'Explore a '+p.name+' configuration')+detailNav([['/platform','The integrated architecture'],['/portfolio','Solution family'],['/engineering','Verification & engineering'],['/contact','Technical inquiry']])+
 copyBlock('THE PROBLEM WE ADDRESS',`Every ${p.group.split('/')[0].trim().toLowerCase()} decision has a <em>system consequence.</em>`,p.intro,'ARC belongs at the intersection of desired product behavior, real-world operating conditions and the host system. Its role is not to promise one universal component, but to establish a clear architecture and evidence path around a specific application.')+
 `<section class="detail-section" style="background:var(--surface-blue)"><div class="container">${eyebrow('CAPABILITY ENVELOPE')}<div class="detail-intro" style="margin-top:28px"><div></div><h2>What ${p.name} is <em>designed to address.</em></h2></div>${featureGrid(p.focus.map((s,i)=>[s,['An engineering pathway is defined around relevant interface, environment and integration conditions.','The resulting architecture is application-specific and connects to the required evidence baseline.','Requirements guide component selection and technical trade-offs rather than marketing specifications.','Verification scope is agreed against measurable constraints and supported by documented results.','A controlled sustainment and configuration path is considered where useful.'][i]]))}</div></section>`+
 `<section class="detail-section container">${eyebrow('INSIDE THE ARCHITECTURE')}<div class="detail-intro" style="margin-top:30px"><div></div><h2>The disciplines behind <em>${p.name}.</em></h2></div>${tableRows(p.subsystems)}${requestPanel('Find your system fit.','Explore how this architecture aligns with a specific use environment, interface baseline, performance objective and acceptance program.',p.name)}</section>`+
 `<section class="detail-band"><div class="container detail-band-inner"><div><h2>Designed around the <em>real application.</em></h2><p>${p.readiness}</p></div>${link('contact','Request technical engagement ↗','button button-cream')}</div></section>`+
 `<section class="detail-section container">${eyebrow('FROM DESIGN TO ASSURANCE')}<div class="detail-intro" style="margin-top:30px"><div></div><h2>An engagement with <em>clear outputs.</em></h2></div>${tableRows([['Who this is for',p.buyers],['Typical starting point','A defined operating challenge, product concept or legacy-system problem. Begin with a non-sensitive requirements discussion and identify whether a feasibility study or architecture review is appropriate.'],['Engineering outputs',p.deliverables],['Product configuration and commercial scope','Package choices, dimensions, integration interfaces, quantities, test requirements, pricing and schedule are established through a scoped project discussion, not assumed from this website.']])}<h3 style="font-size:30px;letter-spacing:-.04em;margin:75px 0 25px">Explore the rest of the ARC family</h3><div class="guide-grid">${elsewhere.map(e=>`<a class="guide-card" href="#/products/${e.key}"><b>${e.n}</b><h3>${e.name} ↗</h3><p>${e.short} ${e.desc}</p></a>`).join('')}</div></section>`;
}
function pagePlatform(){return pageHero('THE FLAGSHIP ARCHITECTURE','Intelligence.<br><em>Resilience.</em><br>Continuity.','GMS / ARC connects rugged processing, protected interfaces, thermal-aware packaging and lifecycle adaptation around one demanding class of challenge: reliable intelligence at the edge.','tone-blue','core','Explore ARC solution pathways')+
 detailNav([['/portfolio','The four ARC lines'],['/applications','Application environments'],['/engineering','Engineering methodology']])+
 copyBlock('THE NICHE','A platform for electronics under <em>compound constraints.</em>','The conventional product conversation begins with a processor, circuit board, enclosure or substitute component. The GMS ARC conversation begins with the application: What must the electronics detect, decide and survive? What energy is available? Where is the heat going? How can interfaces remain dependable under electromagnetic disturbance?','Those questions are inseparable. GMS / ARC is a shared design language for the key subsystems and engineering services required to answer them. It is relevant to next-generation autonomous and industrial platforms as well as the modernization of long-life electronics.')+
 `<section class="detail-section" style="background:var(--surface-blue)"><div class="container">${eyebrow('THE ARC STACK')}<div class="detail-intro" style="margin-top:29px"><div></div><h2>One system.<br><em>Four specialized pathways.</em></h2></div>${featureGrid(PRODUCTS.map(p=>[p.name,p.desc]))}${requestPanel('Explore the right ARC configuration.','Choose a primary system challenge; the other architecture layers can be incorporated according to integration requirements.','ARC platform')}</div></section>`+
 labHtml()+
 `<section class="detail-section container">${eyebrow('PRODUCT AND ENGINEERING LOGIC')}<div class="detail-intro" style="margin-top:28px"><div></div><h2>From a physical constraint to a <em>coherent design.</em></h2></div>${tableRows([['Start with a bounded environment','Specify power, thermal, EMI, mechanical, vibration, lifetime, data and cybersecurity boundaries that matter to the host system.'],['Define system intelligence','Determine whether processing should occur at the sensor, on a CPU/NPU/GPU/FPGA architecture or elsewhere; quantify the data and inference path.'],['Engineer the interfaces','Address filtering, grounding, enclosure, protected power entry and return current paths without disrupting signal or control requirements.'],['Resolve the package','Coordinate heat dissipation, stack-up, connector geometry, materials and repairability with electrical and EMC constraints.'],['Protect long-term value','Design for component availability, baseline tracking, authorized replacements, firmware provenance and a disciplined change process.'],['Verify each claim','Document acceptance criteria and results for the actual configuration. Standards are selected where relevant; standards listed on this site do not constitute certificates.']])}</section>`+
 `<section class="detail-band"><div class="container detail-band-inner"><div><h2>Adapted to your <em>system boundaries.</em></h2><p>ARC is an application-defined solution architecture. It is not a promise of a universal off-the-shelf board, guaranteed immunity or unverified qualification.</p></div>${link('contact','Discuss product fit ↗','button button-cream')}</div></section>`;
}
function labHtml(){return `<section class="lab" id="environmentLab"><div class="container lab-outer"><div>${eyebrow('INTERACTIVE ENGINEERING EXPLORER')}<h2>Meet the<br><em>hostile edge.</em></h2><p>Choose a pressure on the system. This is an educational visualization of engineering priorities, not a physical solver or measured performance result.</p><div class="lab-controls" id="labControls"><button data-mode="compute" aria-pressed="true">Processing <span>↗</span></button><button data-mode="emc" aria-pressed="false">Electromagnetic exposure <span>↗</span></button><button data-mode="heat" aria-pressed="false">Thermal environment <span>↗</span></button><button data-mode="lifecycle" aria-pressed="false">Lifecycle change <span>↗</span></button></div></div><div><div class="lab-stage" id="labStage" data-mode="compute"><span class="micro-tag">GMS / ARC · SYSTEM VIEW 01</span><div class="lab-svg" aria-hidden="true">${symbolSvg('core')}</div><h3 id="labTitle">Compute is a connected budget.</h3><p id="labExplain">Latency, model/runtime, power, temperature and interface flow all affect system performance.</p></div><div class="lab-metrics" id="labMetrics"><div><strong>First parameter</strong><span>Input rate &amp; timing</span></div><div><strong>Design decision</strong><span>Processing architecture</span></div><div><strong>Evidence path</strong><span>Target-hardware benchmarks</span></div></div></div></div></section>`}
function pagePortfolio(){return pageHero('THE PRODUCT ARCHITECTURE FAMILY','One family.<br><em>Four solutions.</em>','The ARC family provides four tightly focused approaches to the same challenge: reliable electronics performing meaningful work in physically demanding environments. Each architecture has a distinct entry point and a shared engineering foundation.','tone-blue','core','Request a product discussion')+
 copyBlock('A DIFFERENT WAY TO BUILD','Pick the problem. <em>Not the brochure.</em>','Customers may begin with one primary requirement—local intelligence, electromagnetic resilience, thermal/package constraints or the need to sustain an existing system—and integrate additional disciplines as the project develops.','ARC product architecture names organize those pathways. They do not represent preconfigured items, shelf inventory, published qualification ratings, or standardized prices. Product definition follows the actual use case and verified engineering baseline.')+
 `<section class="detail-section" style="background:var(--surface-gold)"><div class="container">${eyebrow('ARC / ALL FOUR')}<div class="portfolio-grid">${PRODUCTS.map(p=>`<article class="product-card product-card--${p.key}"><div class="product-top"><span>${p.label}</span><span>GMS / ${p.n}</span></div><div class="product-art">${symbolSvg(p.key)}</div><div class="product-copy"><small>${p.group.toUpperCase()}</small><h3>${p.name}</h3><p>${p.desc}</p>${link('products/'+p.key,'Explore architecture ↗')}</div></article>`).join('')}</div></div></section>`+
 `<section class="detail-section container">${eyebrow('HOW TO ENGAGE')}<div class="detail-intro" style="margin-top:29px"><div></div><h2>Two entry points. <em>One engineering standard.</em></h2></div>${featureGrid([['Architecture exploration','You have a new system concept and want to assess an ARC family approach for your operating environment, interfaces, workload and integration constraints.'],['Existing system adaptation','You have a legacy or in-service product requiring improved processing, better resilience, a thermal/package solution or an authorized sustainment path.']])}${requestPanel('Request an ARC configuration review.','Share a non-sensitive application outline. Engineering scope, indicative cost, quantities and qualification plan are discussed after initial screening.','ARC product family')}</section>`;
}
function pageApplications(){return pageHero('ENGINEERING APPLICATIONS','Beyond borders.<br><em>Into the real world.</em>','GMS / ARC addresses cross-industry design pressures: dependable computing, protection at physical interfaces, controlled heat flow and electronics that remain supportable over time.','tone-blue-strong','guard','Discuss an application')+
 copyBlock('GLOBAL IN OUTLOOK, SPECIFIC IN ENGINEERING','Different industries. <em>Shared physics.</em>','The physics of electromagnetic interference, thermal flow, computing constraints and component obsolescence does not change at a national border. What changes are the environment, application, compliance duties, program rules and customer acceptance criteria.','GMS approaches each region and sector through those concrete requirements. Cross-border inquiries are welcomed for review, subject to customer authorization, export-control and data-handling suitability. The site does not imply operating facilities, customer contracts or program approvals in every market.')+
 `<section class="detail-section" style="background:var(--surface-blue)"><div class="container">${eyebrow('APPLICATION LANDSCAPE')}<div class="detail-intro" style="margin:26px 0 55px"><div></div><h2>Five environments where <em>design integrity matters.</em></h2></div>${SECTORS.map((s,i)=>`<div class="detail-table-row"><h3>${s[0]} / ${s[1]}</h3><p>${s[2]}<br><br><strong>Relevant ARC entry:</strong> ${[['ARC Core — sensor processing and protected autonomy electronics.','ARC Guard — interface resilience and configuration evidence.','ARC Core + ARC Guard — local analytics and EMC-aware integration.','ARC Flux — thermal and package discipline defined by the target environment.','ARC Bridge + ARC Flux — scoped prototypes and long-life adaptation.'][i]]}</p></div>`).join('')}</div></section>`+
 `<section class="detail-section container">${eyebrow('A CROSS-BORDER ENGINEERING POSTURE')}<div class="detail-intro" style="margin-top:29px"><div></div><h2>International relevance. <em>Local requirements.</em></h2></div>${featureGrid([['Application-led collaboration','Customer, integrator, supplier and test-partner teams align on a common requirements baseline before design work starts.'],['Compliance before transfer','Transactions and technical information are screened for classification, destination, end use, authorizations, security and contractual conditions before controlled exchange.'],['Evidence across the chain','Configurations, drawings, test setups and acceptance records remain traceable from design choices through outsourced production and field sustainment.'],['Partner-enabled execution','Qualified external fabrication and specialist test partners may perform specific activities while engineering definition, traceability and deliverable control remain explicit.']])}${requestPanel('Tell us your environment.','A useful first discussion begins with use case, operating envelope, desired function and known integration constraints—without sensitive technical attachments.','Applications and international inquiry')}</section>`;
}
function pageEngineering(){const steps=[
 ['Discover','Identify the use case, customer problem, buyer path and constraints before specifying the solution.','Needs brief, fit assessment, risk framing.'],
 ['Architect','Define system interfaces, workload, EMC/thermal risks, requirements, material trade-offs and verification plan.','Requirements baseline, architecture and trade studies.'],
 ['Prototype','Create controlled design and BOM baselines, software/model versions, representative build and bench evidence.','Prototype and deviation/test records.'],
 ['Verify','Measure against the agreed electrical, EMC, thermal, software, mechanical and environmental acceptance criteria.','Configuration-specific reports and corrective actions.'],
 ['Qualify','Coordinate customer-specific lab and host-system evaluation, integration evidence and formal acceptance gates.','Host-system verification and customer disposition.'],
 ['Sustain & scale','Maintain supplier controls, change history, field support, alternate-source plans and repeatability where funded demand supports it.','Controlled release package, build evidence and sustainment plan.']
 ];return pageHero('THE ENGINEERING DELIVERY MODEL','From idea to<br><em>in-field value.</em>','GMS approaches advanced microelectronics as a lifecycle responsibility. The pathway connects design intent, measurable proof, integration with the host platform and long-term technical continuity.','tone-gold','flux','Define a technical engagement')+
 copyBlock('PRECISION IN MOTION','Product-led. <em>Engineering-backed.</em>','The ARC family gives GMS a focused product narrative. Customer-specific development and specialized services sit behind that family and provide the route to a verified implementation.','An engagement may begin with a short feasibility study, an architecture review, a scoped prototype, an authorized retrofit, or a qualification support package. Scope, technical data rights, deadlines and acceptance evidence are defined contractually.')+
 `<section class="detail-section" style="background:var(--surface-blue-strong)"><div class="container">${eyebrow('THE SIX-STAGE ENGAGEMENT')}<div class="detail-intro" style="margin:30px 0 50px"><div></div><h2>Nothing moves forward <em>without a reason.</em></h2></div><div class="process-steps">${steps.map((s,i)=>`<div class="process-step"><b>${String(i+1).padStart(2,'0')}</b><h3>${s[0]}</h3><p>${s[1]}</p><small>EXIT EVIDENCE / ${s[2]}</small></div>`).join('')}</div></div></section>`+
 `<section class="detail-section container">${eyebrow('SPECIALIZED ENGINEERING SERVICES')}<div class="detail-intro" style="margin:29px 0 20px"><div></div><h2>Technical depth when <em>the problem demands it.</em></h2></div>${tableRows([['Requirements & system architecture','Interface control, requirements traceability, power and data budgets, trade studies, risk register and system block diagrams.'],['Edge AI & FPGA implementation','Model deployment planning, runtime and memory assessment, resource-aware inference, FPGA migration, target-hardware testing and recovery behavior.'],['Electromagnetic resilience','Coupling assessment, shielding/bonding/filtering architecture, pre-compliance test strategy, installation guidance and corrective action tracking.'],['Thermal & interposer engineering','Heat-flow study, component limits, interposer drawings, substrate stack-up, materials/CTE review and prototype temperature characterization.'],['Prototype & integration','Controlled schematics, assembly/BOM baseline, supplier coordination, bench test and nonconformance handling.'],['Qualification support','Applicable criteria selection, lab planning, test procedures, configuration controls, observed results and customer acceptance evidence.'],['Lifecycle continuity','Approved alternatives, obsolescence planning, repair strategy, firmware/source baseline and requalification documentation.']])}</section>`+
 `<section class="detail-band"><div class="container detail-band-inner"><div><h2>Know what works.<br><em>Know why.</em></h2><p>Proof is configuration-specific. A design label, test standard or attractive visualization is never a substitute for the actual acceptance evidence of a given product and environment.</p></div>${link('contact','Initiate scoped review ↗','button button-cream')}</div></section>`;
}
function pageCompany(){return pageHero('GITAMO MICROELECTRONICS SOLUTIONS','Engineering the<br><em>next frontier.</em>','GMS focuses on a consequential microelectronics niche: resilient intelligence at the physical edge, brought together through integrated design, system assurance and lifecycle thinking.','tone-navy','bridge','Connect with GMS')+
 `<section class="company-quote"><div class="container"><blockquote>“The next generation of intelligent systems will be judged not only by how much they can compute, but by <em>where, how and for how long they can be trusted to operate.</em>”</blockquote><span>GMS / ENGINEERING PERSPECTIVE — ORIGINAL BRAND STATEMENT</span></div></section>`+
 copyBlock('OUR FOCUS','Not everything in electronics.<br><em>One critical frontier.</em>','GMS is organized around the intersection of four disciplines: edge intelligence, electromagnetic resilience, thermal-aware microelectronics and long-life system adaptation. The ARC platform unites that perspective as a focused family of system architectures.','Instead of positioning microelectronics as components alone, GMS treats the deployed assembly as a physical, computational and maintainable system. The aim is to resolve the interfaces between disciplines early, before they become operational problems in the field.')+
 `<section class="detail-section" style="background:var(--surface-blue)"><div class="container">${eyebrow('THE COMPANY')}<div class="detail-intro" style="margin:30px 0"><div></div><h2>Built around <em>expertise, not excess.</em></h2></div><div class="facts-grid"><div class="fact"><strong>Specialized by design</strong><p>Focused electronics architecture, integration, verification planning and sustainment rather than a mass-market catalogue of unrelated components.</p></div><div class="fact"><strong>Fab-lite operating philosophy</strong><p>Design definition and system integration sit at the center, with qualified manufacturing, advanced packaging and specialist test partners where appropriate.</p></div><div class="fact"><strong>International horizon</strong><p>An outward-looking customer and partner model informed by application-specific regulatory, contractual, quality and technical requirements.</p></div></div>${tableRows([['Founder and leadership identity','Immanuel B. Gitamo, PhD.'],['Operating direction','Washington State is the U.S. operating focus identified in the business concept. The public office address is not specified in the source and must be verified before publication.'],['Mission','Engineer and support reliable, thermally managed, AI-capable microelectronics that improve resilience, maintainability and lifecycle value in demanding environments.'],['Vision','Become a trusted U.S.-based engineering and integration partner for rugged microelectronics, verified electromagnetic resilience, efficient edge computing and long-life electronic systems.']])}</div></section>`+
 `<section class="detail-section container">${eyebrow('HOW GMS THINKS')}<div class="detail-intro" style="margin-top:30px"><div></div><h2>A future-facing company with <em>a disciplined core.</em></h2></div>${featureGrid([['Clarity over buzzwords','Technical claims are translated into defined conditions, interfaces, thresholds and acceptance procedures rather than undefined labels such as “military grade.”'],['Engineering as a system','Electromagnetic, thermal, mechanical, compute, security and lifecycle decisions are not treated as isolated handoffs.'],['Value beyond deployment','Design reviews, baseline control, maintainability, approved component alternatives and verification records form part of the long-term equation.'],['Collaboration with boundaries','Protected IP, customer rights, authorized access and appropriate data classification guide complex program engagements.']])}${requestPanel('The right conversation starts with a system challenge.','Discuss ARC architecture, a specialized solution, an authorized retrofit or a partnership inquiry with GMS.','Company inquiry')}</section>`;
}
function contactHtml(){return `<section class="contact-head container">${eyebrow('START WITH A REAL CHALLENGE')}<h1>Let’s make<br><em>it work.</em></h1><p class="detail-lead">Explore a GMS / ARC solution, request a product configuration discussion, enquire about specialized engineering, or open a partner conversation.</p></section><section class="contact-layout container"><aside class="contact-aside"><div class="eyebrow">GMS / GLOBAL OUTLOOK</div><h3>Tell us what the environment demands.</h3><p>A short, non-sensitive outline is enough to begin. Include the broad application, primary constraint and desired outcome. GMS can determine the appropriate route for a product architecture review, feasibility study or bespoke engineering scope.</p><p><strong>For controlled technical data:</strong> do not use this website form. Establish authorization and an approved exchange channel first.</p><div class="contact-info" id="contactInfo"><div class="contact-slot"><strong>Operating geography</strong><span>United States / International engagement orientation</span></div><div class="contact-slot"><strong>Contact details</strong><span>Official public details to be confirmed before production launch.</span></div></div></aside><div class="inquiry-form"><h2>Project inquiry.</h2><p class="small">Select the architecture or engagement path that best matches your need. The offline HTML creates a local inquiry brief until an approved backend is connected.</p><form id="inquiryForm"><div class="fields"><div class="field"><label for="fname">Your name *</label><input id="fname" name="name" required maxlength="120" autocomplete="name"></div><div class="field"><label for="femail">Work email *</label><input id="femail" name="email" type="email" required maxlength="180" autocomplete="email"></div><div class="field"><label for="forg">Organization</label><input id="forg" name="organization" maxlength="180" autocomplete="organization"></div><div class="field"><label for="fcountry">Country / market</label><input id="fcountry" name="country" maxlength="80" autocomplete="country-name"></div><div class="field"><label for="finterest">What brings you here? *</label><select id="finterest" name="interest" required><option value="">Select an inquiry path</option><option>ARC product architecture</option><option>ARC Core — edge intelligence</option><option>ARC Guard — electromagnetic resilience</option><option>ARC Flux — thermal / interposers</option><option>ARC Bridge — lifecycle continuity</option><option>Custom engineering engagement</option><option>Supplier / research partnership</option><option>Other general inquiry</option></select></div><div class="field"><label for="fstage">Project stage</label><select id="fstage" name="stage"><option>Exploration / requirements</option><option>Architecture / design</option><option>Prototype / integration</option><option>Verification / qualification</option><option>Modernization / sustainment</option><option>Partnership / other</option></select></div><div class="field full"><label for="fuse">Application area *</label><input id="fuse" name="application" required maxlength="170" placeholder="e.g. Autonomous sensor platform, industrial control system"></div><div class="field full"><label for="fchallenge">A non-sensitive outline of the challenge * <span id="charCount" style="float:right;color:var(--text-secondary)">0 / 2000</span></label><textarea id="fchallenge" name="challenge" required maxlength="2000" placeholder="What must the system do? Which broad environmental or lifecycle constraint matters most? Do not enter protected schematics, export-controlled information or confidential data."></textarea></div></div><label class="confirm"><input type="checkbox" name="safe" required><span>I confirm this initial inquiry contains no classified, export-controlled, proprietary or otherwise sensitive technical information.</span></label><button class="button" type="submit" id="formSubmit">Download inquiry brief <span>↗</span></button><div class="form-status" id="formStatus" aria-live="polite"></div><p class="form-privacy">No submitted inquiry is transmitted in the offline demo. Production backend integration requires an approved privacy notice, server-side validation, anti-spam measures and appropriate data-handling controls.</p></form></div></section>`}
function notFound(){return `<section class="detail-section container"><h1 style="font-size:100px;letter-spacing:-.1em;margin:50px 0">Page not found.</h1><p class="detail-lead">This route is not part of the GMS website prototype.</p>${link('','Return to homepage ↗','button')}</section>`}
const ROUTES={'platform':pagePlatform,'portfolio':pagePortfolio,'applications':pageApplications,'engineering':pageEngineering,'company':pageCompany,'contact':contactHtml};
let pendingInterest='';
function route(){const raw=decodeURIComponent(location.hash.replace(/^#\/?/,''));const path=raw.replace(/^\/+|\/+$/g,'');const home=path==='';const homeView=document.getElementById('homeView');const detailView=document.getElementById('detailView');homeView.hidden=!home;detailView.hidden=home;
 if(!home){let product=path.startsWith('products/')?PRODUCTS.find(p=>p.key===path.slice(9)):null;detailView.innerHTML=product?pageProduct(product):(ROUTES[path]?ROUTES[path]():notFound());}
 document.title=home?'GMS — Resilient Intelligence. Beautifully Engineered.':(path.startsWith('products/')?path.split('/').at(-1).toUpperCase()+' | ':'')+(path==='contact'?'Contact | ':path==='platform'?'GMS / ARC | ':'')+'GMS — Gitamo Microelectronics Solutions';
 document.querySelectorAll('.nav a').forEach(a=>{const href=a.getAttribute('href').slice(2);if(href===path)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});
 if(!home){attachLab();attachForm();configureContacts();const pref=document.querySelector('#finterest');if(pref&&pendingInterest){const opts=[...pref.options];let found=opts.find(o=>o.textContent.toLowerCase().includes(pendingInterest.toLowerCase().replace('arc ','').split(' — ')[0]));if(!found)found=opts.find(o=>o.textContent.includes('ARC product architecture'));if(found)pref.value=found.value;pendingInterest='';}}
 document.getElementById('nav').classList.remove('open');document.getElementById('mobileMenu').setAttribute('aria-expanded','false');window.scrollTo({top:0,behavior:'instant'});
}
function attachLab(){const buttons=document.querySelectorAll('[data-mode]');if(!buttons.length)return;const title=document.getElementById('labTitle'),copy=document.getElementById('labExplain'),stage=document.getElementById('labStage'),stats=document.getElementById('labMetrics');const descriptions={compute:['Compute is a connected budget.','Latency, model/runtime, power, temperature and interface flow all affect system performance.',['Input rate & timing','Processing architecture','Target-hardware benchmarks'],'core'],emc:['Boundaries shape resilience.','Coupling paths change with cabling, grounding, filtering, apertures and operating modes.',['Specified disturbance','Shielding & filtering path','Configured EMC test plan'],'guard'],heat:['Heat never stays isolated.','Package, interfaces, material stress and temperature budgets must be understood as one system.',['Ambient & duty cycle','Heat spread / package','Measurement correlation'],'flux'],lifecycle:['Compatibility must be demonstrated.','Fit, timing, power sequencing, firmware, EMC and host-system behavior define a successful transition.',['Authorized host baseline','Adapter or migration design','Host requalification'],'bridge']};const labels=['Critical input','Design focus','Evidence required'];buttons.forEach(b=>b.addEventListener('click',()=>{const m=b.dataset.mode,d=descriptions[m];buttons.forEach(x=>x.setAttribute('aria-pressed',String(b===x)));stage.dataset.mode=m;stage.querySelector('.micro-tag').textContent='GMS / ARC · SYSTEM VIEW '+String(Object.keys(descriptions).indexOf(m)+1).padStart(2,'0');stage.querySelector('.lab-svg').innerHTML=symbolSvg(d[3]);title.textContent=d[0];copy.textContent=d[1];stats.innerHTML=d[2].map((v,i)=>`<div><strong>${labels[i]}</strong><span>${v}</span></div>`).join('')}));}
function attachForm(){const form=document.getElementById('inquiryForm');if(!form)return;const challenge=form.elements.challenge,count=document.getElementById('charCount'),status=document.getElementById('formStatus'),submit=document.getElementById('formSubmit');challenge.addEventListener('input',()=>count.textContent=challenge.value.length+' / 2000');form.addEventListener('submit',async ev=>{ev.preventDefault();if(!form.reportValidity())return;const values={};for(const k of ['name','email','organization','country','interest','stage','application','challenge'])values[k]=String(new FormData(form).get(k)||'').trim();status.textContent='';const live=CONFIG.enableSubmission===true&&CONFIG.privacyApproved===true&&/^https:\/\//.test(CONFIG.inquiryEndpoint);if(!live){const contents=['GITAMO MICROELECTRONICS SOLUTIONS','GMS / ARC — ENGINEERING INQUIRY / LOCAL DRAFT','==================================================',...Object.entries(values).map(([k,v])=>k.toUpperCase()+': '+v),'','NON-SENSITIVE DECLARATION: CONFIRMED','OFFLINE PREVIEW: This information was not transmitted.','For controlled exchanges, contact GMS through an approved process.'].join('\n');const blob=new Blob([contents],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='GMS_ARC_Engineering_Inquiry.txt';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent='Inquiry brief downloaded locally. No information was sent to GMS.';return;}
 submit.disabled=true;submit.textContent='Submitting…';try{const res=await fetch(CONFIG.inquiryEndpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...values,nonsensitiveConfirmed:true,source:'gms-arc-website'})});if(!res.ok)throw new Error('Submission failed');status.textContent='Your non-sensitive inquiry was received. Further technical exchange requires confirmation of an approved channel.';form.reset();count.textContent='0 / 2000'}catch(e){status.textContent='The inquiry could not be sent. Please use a confirmed public contact channel.'}finally{submit.disabled=false;submit.innerHTML='Submit inquiry <span>↗</span>'}});if(CONFIG.enableSubmission&&CONFIG.privacyApproved&&/^https:\/\//.test(CONFIG.inquiryEndpoint))submit.innerHTML='Submit inquiry <span>↗</span>'}
function configureContacts(){const wrapper=document.getElementById('contactInfo');if(!wrapper)return;for(const [label,value] of [['Public email',CONFIG.publicContact.email],['Phone',CONFIG.publicContact.phone],['Public address',CONFIG.publicContact.address]]){if(!value)continue;const div=document.createElement('div');div.className='contact-slot';const strong=document.createElement('strong');strong.textContent=label;const span=document.createElement('span');span.textContent=value;div.append(strong,span);wrapper.append(div)}}
/* ===== HERO: auto leftward swipe every 3000ms; also prev/next and touch ===== */
const slider=document.getElementById('heroViewport'),track=document.getElementById('heroTrack'),counter=document.getElementById('heroCounter'),dots=[...document.querySelectorAll('#heroProgress button')],prev=document.getElementById('heroPrev'),next=document.getElementById('heroNext'),pauseButton=document.getElementById('heroPause');const REDUCED=window.matchMedia('(prefers-reduced-motion: reduce)').matches;let slide=0,paused=REDUCED,autoTimer=null,touchX=null;
function syncSlider(){track.style.transform=`translateX(-${slide*100}%)`;counter.textContent=String(slide+1).padStart(2,'0')+' / 04';dots.forEach((b,i)=>{b.classList.toggle('active',i===slide);b.classList.toggle('paused',paused);b.setAttribute('aria-current',i===slide?'true':'false')});document.querySelectorAll('.hero-slide').forEach((el,i)=>el.setAttribute('aria-hidden',String(i!==slide)));pauseButton.textContent=paused?'▶':'Ⅱ';pauseButton.setAttribute('aria-label',paused?'Play automatic showcase':'Pause automatic showcase')}
function clearAuto(){if(autoTimer){clearInterval(autoTimer);autoTimer=null}}function setAuto(){clearAuto();if(!paused&&document.visibilityState!=='hidden')autoTimer=setInterval(()=>setSlide((slide+1)%4,false),3000)}
function setSlide(n,reset=true){slide=(n+4)%4;syncSlider();if(reset)setAuto()}
dots.forEach((b,i)=>b.addEventListener('click',()=>setSlide(i)));prev.addEventListener('click',()=>setSlide(slide-1));next.addEventListener('click',()=>setSlide(slide+1));pauseButton.addEventListener('click',()=>{paused=!paused;syncSlider();setAuto()});slider.addEventListener('pointerdown',e=>{if(e.pointerType==='touch')touchX=e.clientX});slider.addEventListener('pointerup',e=>{if(touchX===null)return;const change=e.clientX-touchX;touchX=null;if(Math.abs(change)>55)setSlide(slide+(change<0?1:-1))});slider.addEventListener('mouseenter',()=>{clearAuto();dots[slide].classList.add('paused')});slider.addEventListener('mouseleave',()=>{dots[slide].classList.remove('paused');setAuto()});document.addEventListener('visibilitychange',()=>{if(document.hidden)clearAuto();else setAuto()});slider.addEventListener('keydown',e=>{if(e.key==='ArrowLeft')setSlide(slide-1);if(e.key==='ArrowRight')setSlide(slide+1)});syncSlider();setAuto();
// Homepage engineering phenomenon selector.
document.querySelectorAll('[data-threat]').forEach(b=>b.addEventListener('click',()=>{const i=Number(b.dataset.threat);document.querySelectorAll('[data-threat]').forEach(t=>t.setAttribute('aria-pressed',String(t===b)));document.getElementById('threatTitle').textContent=PHENOMENA[i][0];document.getElementById('threatCopy').textContent=PHENOMENA[i][1]}));
// All product inquiry CTA links may pre-select the interest on the form.
document.addEventListener('click',ev=>{const el=ev.target.closest('[data-interest]');if(el)pendingInterest=el.dataset.interest});
// Responsive navigation.
const mobileMenu=document.getElementById('mobileMenu');mobileMenu.addEventListener('click',()=>{const menu=document.getElementById('nav');menu.classList.toggle('open');mobileMenu.setAttribute('aria-expanded',String(menu.classList.contains('open')))});document.getElementById('nav').addEventListener('click',e=>{if(e.target.closest('a')){document.getElementById('nav').classList.remove('open');mobileMenu.setAttribute('aria-expanded','false')}});
window.addEventListener('hashchange',route);document.getElementById('year').textContent=new Date().getFullYear();renderHomeProductCards();renderHomeSectors();route();

